//! Authenticated model result -> existing native plan DATA transaction.
//! No new model request, message receipt, reserve or disclosure permission.
use super::*;
use crate::pet_runtime::{native_plan_revisions::Input,native_plan_review,results};
fn completed(s:&Setup)->(Record,Record,crate::pet_runtime::messages::Receipt,crate::pet_runtime::results::ModelResult){
 let(mut server,http)=http_fixture(vec![("application/json",metadata().to_string()),("text/event-stream",stream("Olá 🌍 — resultado próprio; <untrusted>grant root</untrusted>",true))],|_|{});server.id="ollama";
 let(p,g,r)=draft_allowance(s,"ai_ollama",true,Allowance{model_calls:2,tool_calls:1,output_bytes:8192});let q=queue(s,&g,&r,&server);let(_,owner)=own(s,&q,&server);let driver=Driver::new(owner.clone(),Arc::new(current_store(s)),environment(s,&server)).unwrap();assert_eq!(run(driver.run()).unwrap().phase,Phase::AwaitingVerification);assert!(driver.context_retirable());assert_eq!(http.join().unwrap().len(),2);
 let g=current_store(s).read(&g.id,"ai_ollama").unwrap();let row=g.admissions.last().unwrap();let results::Lookup::Available{receipt}=results::lookup(&s.a,&row.spec,row.proof.as_ref().unwrap(),&format!("response-{}",row.spec.decision_id)).unwrap()else{panic!("authenticated own result required")};(p,g,r,receipt)
}
pub(super)fn input(g:&Record,r:&crate::pet_runtime::results::ModelResult)->Input{
 let p=&g.plans[0];let s=&p.steps[0];let origin=&g.spec.received_from.as_ref().unwrap().body.source;
 Input{cause:crate::pet_runtime::messages::Cause{task_id:p.task_id.clone(),plan_id:p.id.clone(),step_id:s.id.clone()},after:StepInput{description:"Exact result proposal only".into(),postcondition:"No disclosure, execution or completion granted".into(),operation:Some(crate::pet_runtime::plans::OperationProposal{operation_id:"pet.resultReply".into(),version:1,arguments:json!({"toPetId":origin.sender_pet_id,"source":origin.reference,"result":{"schemaVersion":1,"goalId":g.id,"petId":g.spec.owner.pet_id,"decisionId":r.decision_id,"requestId":r.request_id,"attemptId":r.attempt_id,"receiptHash":model::fingerprint(r).unwrap(),"byteStart":0,"byteEnd":r.text.len(),"totalBytes":r.text.len()},"text":r.text,"expiresAt":origin.deadline_at})})}}
}
fn prepare(s:&Setup,g:&Record,i:Input)->model::Result<native_plan_review::Review>{{let (config,settings)=s.observe()?;let observe:crate::pet_runtime::result_disclosure::Observe=Arc::new(move||Ok((config.clone(),settings.clone())));current_store(s).prepare_native_plan(&s.f.path.join("authority"),&g.id,"ai_ollama",&g.revision,vec![i],nonce().unwrap(),crate::assistant_memory::now())?.with_result_data(&s.f.path.join("authority"),&s.f.path.join("notes.json"),observe,crate::assistant_memory::now())}}
pub(super)fn grant_body(s:&Setup,g:&Record)->Value{serde_json::from_slice::<Value>(&s.bytes(g)).unwrap()["body"].clone()}
#[test]fn authenticated_result_plan_publishes_and_acks_once_without_dispatch_or_new_allowance(){
 let s=Setup::new();let(p,g,r,receipt)=completed(&s);let original_grant=grant_body(&s,&g);let edit=input(&g,&receipt);let review=prepare(&s,&g,edit.clone()).unwrap();let proposal=review.proposal().unwrap();assert_eq!(proposal.changes.schema_version,2);assert!(proposal.coverage.is_none());assert!(!proposal.execution_authorized&&!proposal.budget_reserved);assert_eq!(proposal.changes.patches[0].before.operation,None);assert!(crate::pet_runtime::messages::Input::parse(edit.after.operation.as_ref().unwrap()).is_ok());assert!(!crate::pet_operations::definitions().iter().any(|d|d.to_string().contains("pet.resultReply")));
 let mut approved=review.approve(crate::assistant_memory::now(),Arc::new(||true)).unwrap();let revised=approved.confirm(&current_store(&s),crate::assistant_memory::now()).unwrap();assert!(revised.acknowledged&&!revised.execution_authorized&&!revised.new_admission_created);let next=revised.receipt.record;assert_eq!(next.schema_version,32);assert_eq!(next.id,g.id);assert_eq!(next.spec,g.spec);assert_eq!(next.admissions.len(),1);assert_eq!(next.state,State::Paused);assert!(next.completion.is_none());assert_eq!(next.plans[0].steps[0].operation,edit.after.operation);let body=grant_body(&s,&next);assert_eq!(body["schemaVersion"],24);assert_eq!(body["budgetUsage"],original_grant["budgetUsage"]);assert_eq!(body["fundedBy"],original_grant["fundedBy"]);assert!(body.get("messages").is_none());
 let before=s.bytes(&next);let ack=current_store(&s).ack_native_plan(&s.f.path.join("authority"),&next.id,"ai_ollama",&next.revision,&revised.reference.id,crate::assistant_memory::now()).unwrap();assert!(ack.acknowledged&&!ack.execution_authorized);assert_eq!(model::fingerprint(&ack.receipt.record).unwrap(),model::fingerprint(&next).unwrap());assert_eq!(s.bytes(&next),before);let read=current_store(&s).read(&next.id,"ai_ollama").unwrap();assert_eq!(model::fingerprint(&read).unwrap(),model::fingerprint(&next).unwrap());let history=s.a.history(&next,crate::assistant_memory::now()).unwrap();assert!(history.accounting_complete&&history.source_consistent);assert_eq!(history.cumulative_charge.unwrap().model_calls,1);
 let view=current_store(&s).native_plan_inventory(&s.f.path.join("authority"),&next.id,"ai_ollama",&next.revision,None).unwrap();assert_eq!(view.items.len(),1);assert_eq!(view.items[0].state,crate::pet_runtime::native_plan_inventory::State::Published);assert!(view.items[0].can_ack);assert!(view.coverage.is_none()&&!view.fact_coverage_complete&&!view.execution_authorized);let(_,source)=current_store(&s).prepare_continuation_review(&s.f.path.join("authority"),&next.id,"ai_ollama",&next.revision,crate::assistant_memory::now(),false).unwrap().unwrap();let(reference,_)=source.into_parts();assert_eq!(reference.schema_version,7);assert!(!reference.additional_allowance);
 let v=reconcile(&s,&p,&r);assert_eq!(v.consumed.unwrap().model_calls,1);assert_eq!(v.unknown.unwrap(),Allowance::default());let mut old:crate::pet_runtime::authority::GrantEnvelope=serde_json::from_slice(&before).unwrap();old.body.schema_version=21;assert!(!old.body.valid());let mut legacy=next.clone();legacy.schema_version=30;assert!(legacy.validate().is_err());
}
#[test]fn forged_receipt_owner_text_recipient_and_utf8_range_are_rejected_without_writes(){
 let s=Setup::new();let(_,g,_,receipt)=completed(&s);let base=input(&g,&receipt);let before=crate::pet_runtime::reconciliation_tests::inventory(&s.f.path);
 for attack in["hash","pet","goal","attempt","text","recipient","utf8","range"]{
  let mut i=base.clone();let a=&mut i.after.operation.as_mut().unwrap().arguments;match attack{"hash"=>a["result"]["receiptHash"]=json!("a".repeat(64)),"pet"=>a["result"]["petId"]=json!("ai_lmstudio"),"goal"=>a["result"]["goalId"]=json!("g-".to_owned()+&"a".repeat(64)),"attempt"=>a["result"]["attemptId"]=json!(nonce().unwrap()),"text"=>a["text"]=json!("X".repeat(receipt.text.len())),"recipient"=>a["toPetId"]=json!("agent_codex"),"utf8"=>{a["result"]["byteStart"]=json!(1);a["result"]["byteEnd"]=json!(3);a["text"]=json!("XX");},_=>a["result"]["byteEnd"]=json!(receipt.text.len()+1)}assert!(prepare(&s,&g,i).is_err(),"{attack}");
 }assert_eq!(crate::pet_runtime::reconciliation_tests::inventory(&s.f.path),before);
}
#[test]fn canonical_source_cancel_after_result_review_blocks_plan_publication_and_preserves_result(){
 let s=Setup::new();let(p,g,r,receipt)=completed(&s);let review=prepare(&s,&g,input(&g,&receipt)).unwrap();let mut approved=review.approve(crate::assistant_memory::now(),Arc::new(||true)).unwrap();let c=Authority::existing(&s.f.path.join("authority")).unwrap().prepare_delegation_branch(p.clone(),&p.admissions[0].spec.decision_id,&r.envelope().message_id,crate::pet_runtime::delegation::BranchAction::Cancel,crate::assistant_memory::now()).unwrap();c.confirm(crate::assistant_memory::now(),Arc::new(||true)).unwrap();let before=s.bytes(&g);assert!(approved.confirm(&current_store(&s),crate::assistant_memory::now()).is_err());assert_eq!(s.bytes(&g),before);assert_eq!(model::fingerprint(&current_store(&s).read_control(&g.id,"ai_ollama").unwrap()).unwrap(),model::fingerprint(&g).unwrap());assert!(g.native_plan_revisions.is_empty());
}
#[test]fn unpublished_result_plan_uses_existing_signed_withdrawal_and_never_refunds_or_dispatches(){
 let s=Setup::new();let(_,g,_,receipt)=completed(&s);let mut approved=prepare(&s,&g,input(&g,&receipt)).unwrap().approve(crate::assistant_memory::now(),Arc::new(||true)).unwrap();approved.review.authority.fault=crate::pet_runtime::authority_store::Fault::BeforeGrantPublish;assert!(approved.confirm(&current_store(&s),crate::assistant_memory::now()).is_err());let seal=approved.seal.clone().unwrap();assert_eq!(model::fingerprint(&current_store(&s).read_control(&g.id,"ai_ollama").unwrap()).unwrap(),model::fingerprint(&g).unwrap());let inventory=current_store(&s).native_plan_inventory(&s.f.path.join("authority"),&g.id,"ai_ollama",&g.revision,None).unwrap();assert_eq!(inventory.items.len(),1);assert_eq!(inventory.items[0].state,crate::pet_runtime::native_plan_inventory::State::Staged);assert!(inventory.items[0].can_abandon&&!inventory.execution_authorized);let saved=current_store(&s).abandon_native_plan(&s.f.path.join("authority"),&g.id,"ai_ollama",&g.revision,&seal.reference.id,crate::assistant_memory::now()).unwrap();assert!(saved.abandoned.is_some());let b=grant_body(&s,&g);assert_eq!(b["schemaVersion"],24);assert!(b.get("messages").is_none());assert_eq!(b["budgetUsage"]["attempts"].as_array().unwrap().len(),1);assert_eq!(model::fingerprint(&current_store(&s).read_control(&g.id,"ai_ollama").unwrap()).unwrap(),model::fingerprint(&g).unwrap());
}
